import os
import urllib3
from configobj import ConfigObj
from provisioning_helper import execute_tenant_api
import json
http = urllib3.PoolManager(cert_reqs="CERT_NONE")

'''Get Gateway URL'''
pwd = os.path.dirname(os.path.abspath(__file__))
properties_path = os.path.join(pwd, "../properties/appviewx.properties")
avx_properties = ConfigObj(properties_path)
gw_url = avx_properties['GATEWAY_BASE_URL']
gw_key = avx_properties['GATEWAY_KEY']
gw_url = gw_url if gw_url.endswith('/') else gw_url + "/"
cluster_provisioning_gateway_url = "<%provisioning_url%>"


tenant_ids = "<%internal_tenant%>".split(",")
cluster_type = "<%cluster_type%>"
source_tag = "<%source_tag%>"
createdFor = {"MSP":"MSP","Tenants":"Tenant","MSP Tenants": "TenantOfMSP"}[cluster_type]

#DNS Related Variables
enable_proxy = True
record_type = "CNAME"
bearer_token = str("<%Integrations.Cloudflare.token%>")

#Default headers for API within provisioning
headers = {
    "Content-Type": "application/json",
    "sessionId": "<%sessionId%>",
    "Accept": "application/json"
}

def decyrpt_process(pwd):
    """
    Helps to decrpt the password using the jar files
    """
    header_data = {"Content-Type": "application/json"}
    url = "http://localhost:9090/services/decrypt?gwsource=test"
    pwd = pwd.get("encryptedValue", "")
    data = {"payload": pwd}
    method = "POST"
    encoded_data = json.dumps(data).encode("utf-8")
    http = urllib3.PoolManager(cert_reqs="CERT_NONE")
    try:
        response = http.request(method, url=url, body=encoded_data, headers=header_data)
        if response.status == 200:
            response = json.loads(response.data.decode("utf-8"))
            return response.get("response")
        else:
            raise Exception(
                "Error while getting password : "
                + str(json.loads(response.data.decode("utf-8")))
            )
    except Exception as e:
        raise Exception("Error while getting password : " + str(e))


try:
    from tenentQueueTokenMap import max_token_map
except:
    max_token_map = {}


if cluster_type in ["MSP","MSP Tenants"]:
    zone_id = str("<%Integrations.Cloudflare.config.msp_zone_id%>")
else:
    zone_id = str("<%Integrations.Cloudflare.config.zone_id%>")

def move_tenant():
    for i in range(0, len(tenant_ids), 5):
        tenants = tenant_ids[i:i+5]
        payload = {
                    "payload" :{
                       "source" : "CANARY",  
                       "destination": "PRODUCTION",
                       "tenantIds": tenants
                     }
                    }
        url = f"https://{cluster_provisioning_gateway_url}/avxapi/saas-tenant-metadata-move?gwkey=f000ca01&gwsource=external"
        headers = {
                    "Content-Type": "application/json",
                    "Accept": "application/json"
               }
        response = execute_tenant_api(method="POST", url=url, payload=payload)
        # response = http.request("POST", url, headers=headers, body = json.dumps(payload))
        AVX::LOG(str(response.data.decode('utf-8')))
        if response and response.status == 200:
            AVX::LOG(f"{str(tenants)} moved to PRODUCTION successful")
        else:
            raise Exception(f"{str(tenants)} moved to PRODUCTION Failed")


def get_root_domain():
    if cluster_type in ["MSP", "MSP Tenants"]:
        url = gw_url + "avxapi/saas-msp-domain?gwkey=f000ca01&gwsource=external"
    else:
        url = gw_url + "avxapi/saas-get-root-domain?gwkey=f000ca01&gwsource=external"
    response = http.request("GET", url, headers=headers)
    if response and response.status == 200:
        if cluster_type in ["MSP", "MSP Tenants"]:
            root_domain = json.loads(response.data.decode("utf-8"))["response"]
        else:
            root_domain = json.loads(response.data.decode("utf-8"))["response"]["rootDomain"]
        return root_domain
    else:
        raise Exception(f"Unable to get root domain. Error - {response.data.decode('utf-8')}")


def get_clusters():

    try:
        global clusterName
        global region
        global web_url

        url = gw_url + f"avxapi/saas-get-paired-cluster-by-tagname?gwkey=f000ca01&gwsource=external&tagName={source_tag}&createdFor={createdFor}"
        response = http.request("GET", url, headers=headers)
        if response and response.status == 200:
            response = json.loads(response.data.decode("utf-8"))
            for i in response.get("response"):
                if i["clusterType"] == "COMPUTE":
                    region = i.get("region")
                    web_url = i.get("url")
                if i["clusterType"] == "DB":
                    clusterName = i.get("clusterName")
        AVX::LOG(f"Cluster Name - {clusterName}, Region - {region}")
        return
    except Exception as e:
        raise Exception(f"Unable to get cluster details from tag. Error - {e}")


def fetch_msp_tenants(selectedTenant):

    url = f"{gw_url}avxapi/saas-get-all-msp-tenants-by-cluster?gwkey=f000ca01&gwsource=external&excludeOffBoardedTenant=true&createdFor={createdFor}"
    payload = {
        "payload": [
            {
                "clusterName": clusterName,
                "region": region
            }
        ]
    }
    response = http.request("POST", url, headers=headers, body=json.dumps(payload))
    if response and response.status == 200:
        response = json.loads(response.data.decode("utf-8"))
        for cluster in response["response"]:
            associated_tenants = cluster.get("associatedTenants", {})
            for tenant_provider, tenants in associated_tenants.items():
                for tenant in tenants:
                    if tenant.get("tenantName") == selectedTenant:
                        return tenant,tenant_provider
        raise Exception(f"Unable to find MSP Tenant - {selectedTenant} . Error - {str(response)}")
    else:
        raise Exception(f"Unable to fetch MSP Tenants. Error - {response.data.decode('utf-8')}")

def fetch_source_id(msp):
    url = gw_url + f"avxapi/saas-msp-metadata?gwkey=f000ca01&gwsource=external&mspId={msp}"
    response = http.request("GET", url, headers=headers)
    if response and response.status == 200:
        response = json.loads(response.data.decode("utf-8"))
        return response.get("response").get("companyName")
    raise Exception(f"Unable to fetch source id. Error - {response.data.decode('utf-8')}")


def get_tenants(selectedTenant):

    if cluster_type == "MSP":
        url = f"{gw_url}avxapi/saas-msp-get-all-by-cluster?gwkey=f000ca01&gwsource=external&excludeOffBoardedTenant=true"
    else:
        url = f"{gw_url}avxapi/saas-tenant-get-all-by-cluster?gwkey=f000ca01&gwsource=external&excludeOffBoardedTenant=true"
    payload = {
        "payload": [
            {
                "clusterName": clusterName,
                "region": region
            }
        ]
    }
    response = http.request("POST", url, headers=headers, body=json.dumps(payload))
    if response and response.status == 200:
        response = json.loads(response.data.decode("utf-8"))
        for tenant in response["response"][0]["tenants"]:
            if tenant.get("tenantName") == selectedTenant:
                return tenant
        raise Exception(f"Unable to find tenant - {selectedTenant}. Error -  {str(response)}")
    else:
        raise Exception(f"Unable to fetch {cluster_type}. Error -  {response.data.decode('utf-8')}")


def map_tenant_in_cluster(tenant_info, retry_count=0):

    url = f"https://{cluster_provisioning_gateway_url}/avxapi/saas-tenant-metadata-propagate?gwkey=f000ca01&gwsource=external"
    headers = {
        "Content-Type": "application/json"
    }
    payload = {
        "payload": {
            "_id": tenant_info["tenantId"],
            "tenant_name": tenant_info["tenantName"],
            "email": tenant_info["email"],
            "businessUnitId": tenant_info["tenantName"],
            "db_config": {
                "database_host": tenant_info["dbInfo"]["url"],
                "snapshot_id": tenant_info["dbInfo"]["dbSnapshotId"],
                "authentication_db": "admin",
                "username": tenant_info["dbInfo"]["username"],
                "password": decyrpt_process(tenant_info["dbInfo"]["password"])
            },
            "max_token_map": max_token_map,
            "sourceId": sourceId
        }
    }
    response = execute_tenant_api(method="PUT", url=url, payload=payload)
    # response = http.request("PUT", url, headers=headers, body=json.dumps(payload))
    AVX::LOG(response.data.decode('utf-8'))
    if response.status == 200:
        return None
    elif retry_count < 2:
        map_tenant_in_cluster(tenant_info,retry_count=retry_count + 1)
    else:
        raise Exception(response.data.decode('utf-8'))


def get_record(fqdn):
    """
    Fetches record from cloudfare with the dns name - fqdn
    """
    url = f"https://api.cloudflare.com/client/v4/zones/{zone_id}/dns_records?name={fqdn}"

    headers = {
                "Content-Type": "application/json",
                "Authorization": f"Bearer {bearer_token}"
            }
    response = http.request("GET", url, headers=headers)
    response = json.loads(response.data)
    rec_id = ""
    for i in response["result"]:
        if i["name"] == fqdn:
            rec_id = i["id"]
    AVX::LOG(f"DNS Record ID - {rec_id}")
    return rec_id


def update_record(rec_id, name, target):

    """
    Updates CNAME record in cloudfare with the new target for the record id - rec_id
    """
    payload = {
                "type": record_type,
                "name": name,
                "content": target,
                "ttl": 360,
                "priority": 10,
                "proxied": enable_proxy
            }

    url = f"https://api.cloudflare.com/client/v4/zones/{zone_id}/dns_records/{rec_id}"
    headers = {
                "Content-Type": "application/json",
                "Authorization": f"Bearer {bearer_token}"
            }
    response = http.request("PUT", url, headers=headers, body=json.dumps(payload))
    if response.status == 200:
        AVX::LOG(str(response.data.decode('utf-8')))
        return response
    else:
        raise Exception(str(response.data.decode('utf-8')))



def move_tenant_to_old_cluster(tenant):

    try:

        global  sourceId

        sourceId = ""

        root_domain = get_root_domain()
        AVX::LOG(f"Root Domain - {root_domain}")

        #Get Cluster Details from Tag
        get_clusters()

        #Based on the cluster type fetch tenants
        if cluster_type in ["MSP Tenants"]:
            tenant_info, msp = fetch_msp_tenants(tenant)
            sourceId = fetch_source_id(msp)
        else:
            tenant_info = get_tenants(tenant)

        #Frame dns details of tenant
        tenant_name = tenant_info["tenantName"]
        dns_name = tenant_info["tenantId"]
        cc_dns_name = f"{tenant_name}-cc.{root_domain}"
        cc_secure_dns_name = f"{tenant_name}-cc-secure.{root_domain}"
        ocsp_dns_name = f"{tenant_name}-ocsp.{root_domain}"
        aep_dns_name = f"{tenant_name}-aep.{root_domain}"

        #Map tenant details into new cluster redis
        try:
            map_tenant_in_cluster(tenant_info)
        except Exception as e:
            AVX::LOG("Mapping tenant details into redis failed.")
            raise Exception(repr(e))

        #Updated the DNS records of the tenants
        try:
            AVX::LOG("Fetching DNS Records")
            cluster_rec_id = get_record(dns_name)
            update_record(cluster_rec_id, dns_name, web_url)

            if cluster_type in  ["Tenants","MSP Tenants"]:
                cc_rec_id = get_record(cc_dns_name)
                update_record(cc_rec_id, cc_dns_name, web_url)

                cc_secure_rec_id = get_record(cc_secure_dns_name)
                update_record(cc_secure_rec_id, cc_secure_dns_name, "<%provisioning_url%>")

                ocsp_rec_id = get_record(ocsp_dns_name)
                update_record(ocsp_rec_id, ocsp_dns_name, web_url)

                aep_rec_id = get_record(aep_dns_name)
                update_record(aep_rec_id, aep_dns_name, web_url)

            AVX::LOG("DNS Records updated successfully")

        except Exception as e:
            AVX::LOG("Record updation Failed")
            raise Exception(e)
        return
    except Exception as e:
        raise Exception(repr(e))

if __name__ == "__main__":
    try:
        if "<%infraUpgradeType%>" == "EKS Version Upgrade":
            AVX::LOG("EKS Version Upgrade Selected. Moving tenant back to old cluster")
            for tenant in tenant_ids:
                AVX::LOG(f"Tenant - {tenant}")
                move_tenant_to_old_cluster(tenant)
        else:
            AVX::LOG("Moving tenant back to production pods")
            move_tenant()
        AVX::OUTPUT({})
    except Exception as e:
        AVX::LOG(str(e))
        AVX::OUTPUT({},2)

