def deleteGridFileWithTestFlag(snapshotId, collectionName):
    if snapshotId == 'default':
        database = 'appviewx'
    else:
        database = snapshotId + '@appviewx'

    db = client[database]
    fs = GridFS(db, collectionName)
    query = {
        "metadata.isTestCC": true
    }
    cursor = db[collectionName + ".files"].find(query)
    deleted_count = 0
    for file_doc in cursor:
        fs.delete(file_doc["_id"])
        deleted_count += 1
    AVX::LOG(f"Deleted {deleted_count} files uploaded for CC test purpose")

def removeFileWithTestFlag(snapshotId, collectionName):
    if snapshotId == 'default':
        database = 'appviewx'
    else:
        database = snapshotId + '@appviewx'
    db = client[database]
    collection = db[collectionName]
    deleteResult = collection.delete_many({"isTestCC": true})
    AVX::LOG("Documents deleted = "+str(deleteResult.deleted_count))


